-- Queer Atlas: Colombo, Sri Lanka city package. Verified 2026-09-14; idempotent.
begin;
with s(name,type,description,vibe,hours,link,location,lat,lng,intel) as (values
('The Love Bar at Flamingo House','bar','A hidden bar inside Flamingo House where tropical colour, mischievous interiors and late cocktails replace any need for a rainbow sign. Love Bar is mixed, but its recurring queer reputation and Colombo 7 setting make it one of the city''s more useful public social rooms when there is no permanent dedicated gay bar.','maximalist Colombo 7 cocktail theatre with a quietly queer following','Evening-led and programme-dependent; verify the current opening night and reservation policy directly before travel.','https://www.facebook.com/TheLoveBarColombo/','58A Horton Place, Colombo 07, Sri Lanka',6.9148,79.8716,'{"queue_wait":"The hidden-bar format and event nights make reservations more useful than relying on a street queue. Confirm that Love Bar itself is operating before heading to Flamingo House.","best_nights":"Choose a currently advertised DJ, themed or community night. The queer signal belongs to the crowd and programme, not every ordinary service night.","crowd_mix":"Colombo creatives, queer friend groups, fashion and media circles, expats and mixed cocktail crowds share a compact late room.","dress_code":"Expressive smart casual suits the maximalist setting. Bring identification and keep photography consent-based.","staff_inclusivity":"Love Bar has a sustained queer-friendly reputation and has hosted community-facing nights, but it is a mixed venue without a published LGBTQ+ safeguarding policy. Check the present event and staff response rather than assuming blanket protection.","source_urls":["https://www.facebook.com/TheLoveBarColombo/","https://www.bars10.com/LK/Colombo/151565585195534/The-Love-Bar-Colombo"],"research_status":"editorial_review_consensus","updated_at":"2026-08-29T00:00:00Z"}'::jsonb),
('Barefoot Garden Café','cafe','Behind Barefoot''s handloom shop sits a garden that has spent decades mixing lunch, wine, Sunday jazz, theatre, art launches and political conversation. It is a mainstream café rather than an LGBTQ+ venue, yet its creative programme and community reputation make it a low-pressure daytime meeting point with genuine local texture.','leafy Galle Road courtyard where books, jazz and Colombo''s progressive circles mingle','Mon-Sat 10:00-19:00; Sunday and Poya days 10:00-18:00. Event hours may differ.','https://barefootceylon.com/pages/cafe','704 Galle Road, Colombo 03, Sri Lanka',6.8888,79.8563,'{"queue_wait":"Lunch, Sunday Jazz and launches can fill the garden; booking is useful for a group or programme date, while an ordinary weekday visit is usually more fluid.","best_nights":"Visit by day for the courtyard and bookshop energy, or choose Sunday Jazz and a named art, theatre or book event for a more social crowd.","crowd_mix":"Artists, writers, designers, diplomats, progressive Colombo regulars, families and travellers create an intergenerational cultural room.","dress_code":"Tropical everyday clothing fits. The garden is relaxed, while launches and performances bring a more art-scene polish.","staff_inclusivity":"Barefoot is a mixed cultural venue with a progressive community reputation, not a declared queer safe space. Its public event history supports relevance, but sensitive support should still go through a community organisation.","source_urls":["https://barefootceylon.com/pages/cafe"],"research_status":"editorial_review_consensus","updated_at":"2026-08-29T00:00:00Z"}'::jsonb),
('Jetwing Colombo Seven','hotel','A contemporary city hotel on the Ward Place side of Colombo 7, with an infinity pool and rooftop bar above the traffic. It gives couples a quieter residential base near museums and cafés, plus a staffed retreat from a scene where discretion still matters more than proximity to a gay district.','Cinnamon Gardens calm capped by an infinity pool and skyline bar','Hotel open daily; Sri Lankan standard hotel times are approximately check-in 14:00 and check-out 12:00. Confirm on the reservation.','https://www.jetwinghotels.com/jetwingcolomboseven/','57 Ward Place, Colombo 07, Sri Lanka',6.914,79.8734,'{"queue_wait":"Standard arrival peaks gather around afternoon check-in. Reserve the rooftop bar or spa separately and confirm room and companion details before arrival.","best_nights":"Sunset at the rooftop bar gives the strongest hotel experience; use a confirmed ride for any later event elsewhere in Colombo.","crowd_mix":"International and regional travellers, business guests, city-break couples and local rooftop diners favour the Colombo 7 address.","dress_code":"Smart casual suits the rooftop and public areas; standard pool, spa and fitness attire applies upstairs.","staff_inclusivity":"Jetwing publishes direct property contact and extensive facilities but no Colombo-specific LGBTQ+ protocol. Confirm names, room setup and visitor rules privately; do not treat a travel-directory label as staff-training evidence.","source_urls":["https://www.jetwinghotels.com/jetwingcolomboseven/","https://www.jetwinghotels.com/jetwingcolomboseven/location/"],"research_status":"editorial_review_consensus","updated_at":"2026-08-29T00:00:00Z"}'::jsonb),
('Cinnamon Grand Colombo','hotel','A 501-room institution on Galle Road with a deep restaurant bench, pool and spa beside Crescat and the seafront corridor. The scale creates anonymity and choice: useful for travellers who want full service, several meeting options and fewer reasons to explain a private evening plan outside the hotel.','grand-scale Colombo 3 hospitality with enough dining to build a night indoors','Hotel open daily; flexible arrival products are offered. Confirm the booked check-in and checkout conditions directly.','https://www.cinnamonhotels.com/cinnamon-grand-colombo','77 Galle Road, Colombo 03, Sri Lanka',6.9187,79.8483,'{"queue_wait":"A large convention hotel can have concentrated group arrivals. Confirm the exact flexible-stay product, room configuration and any late arrival directly.","best_nights":"Use its restaurant range and central position for a contained first evening or a low-friction meeting before a separately verified event.","crowd_mix":"Corporate and diplomatic guests, tour groups, affluent local diners, conference delegates and international leisure travellers fill a large property.","dress_code":"Polished casual works through most public areas; individual dining rooms, pool and spa have their own conventional expectations.","staff_inclusivity":"Cinnamon documents broad hospitality facilities and group-wide gender-inclusion work, but no property-specific LGBTQ+ guest protocol was found. Direct confirmation is appropriate for sensitive requests.","source_urls":["https://www.cinnamonhotels.com/cinnamon-grand-colombo","https://www.cinnamonhotels.com/hotel-contact-information"],"research_status":"editorial_review_consensus","updated_at":"2026-08-29T00:00:00Z"}'::jsonb),
('Shangri-La Colombo','hotel','Ocean views, seven restaurants and bars, a spa and direct mall access make this the most contained luxury landing pad on Galle Face. It works when controlled transport, staffed public areas and a broad international crowd matter more than neighbourhood intimacy or a local boutique mood.','oceanfront high-rise sanctuary connected to One Galle Face','Hotel open daily; check-in 14:00 and check-out 12:00.','https://www.shangri-la.com/colombo/shangrila/','1 Galle Face, Colombo 02, Sri Lanka',6.9285,79.8444,'{"queue_wait":"Official check-in begins at 14:00 and checkout is noon. Express services exist, but airport transfers and busy event periods should be arranged in advance.","best_nights":"Choose sunset, dinner or a mall-linked evening when a contained and highly staffed route is useful. It has no recurring queer programme of its own.","crowd_mix":"Luxury leisure guests, executives, conference groups, mall visitors and affluent local diners create an international public environment.","dress_code":"Smart casual fits the lobby and dining rooms; pool, spa and gym areas use standard resort attire.","staff_inclusivity":"The hotel publishes accessible facilities, personalised service and express arrival options, but no Colombo-specific LGBTQ+ training claim. Confirm privacy, names and companion access in writing when material.","source_urls":["https://www.shangri-la.com/colombo/shangrila/","https://www.shangri-la.com/colombo/shangrila/about/"],"research_status":"editorial_review_consensus","updated_at":"2026-08-29T00:00:00Z"}'::jsonb)
), upd as (update public.places p set type=s.type,description=s.description,vibe=s.vibe,hours=s.hours,link=s.link,location=s.location,lat=s.lat,lng=s.lng,venue_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from s where lower(trim(p.city))='colombo' and lower(trim(p.name))=lower(s.name) returning p.id)
insert into public.places(name,city,type,description,vibe,hours,link,location,lat,lng,venue_intel,seo_indexable,seo_quality_status) select name,'colombo',type,description,vibe,hours,link,location,lat,lng,intel,true,'approved' from s where not exists(select 1 from public.places p where lower(trim(p.city))='colombo' and lower(trim(p.name))=lower(s.name));

with s(name,type,provider_name,contact,booking_link,description,hours,link,location,vibe,tags,source) as (values
('EQUAL GROUND','other','EQUAL GROUND Sri Lanka','equalground@gmail.com · +94 11 4334277-79 · +94 11 2075326','https://www.equal-ground.org/','Sri Lanka’s oldest diverse LGBTQI+ rights organisation provides trilingual counselling, legal and health referrals, empowerment work, advocacy and Colombo Pride. Its safe-space location is contact-led for community security.','Office, helpline and programme-led; contact before visiting.','https://www.equal-ground.org/','Confidential contact-led safe space, Colombo, Sri Lanka','national LGBTQI+ advocacy, counselling and Pride anchor',array['service','social','cultural']::text[],'EQUAL GROUND official website'),
('National Transgender Network Trust','other','National Transgender Network Trust Sri Lanka','ntnsrilanka@gmail.com · +94 76 045 5850','https://www.facebook.com/ntnsrilanka/','A trans-led network offering legal, medical, emotional and socioeconomic support, human-rights documentation, clinics and a hotline for trans and gender-diverse people.','Hotline and programme-led; contact for current drop-in access.','https://www.facebook.com/ntnsrilanka/','Contact-led service, Colombo district, Sri Lanka','trans-led legal, health, shelter and emotional support',array['service','social']::text[],'National Transgender Network and Feminist Opportunities Now'),
('Family Planning Association Sri Lanka','other','Family Planning Association of Sri Lanka','info@fpasrilanka.org · +94 11 2555455 · +94 11 2580915','https://www.fpasrilanka.org/ask-sri','A mainstream sexual and reproductive-health provider with anonymous Ask Sri support and medical, informational and psychological services. Confirm the appropriate clinic before sharing sensitive details.','Mon-Fri 08:30-16:30 except public and bank holidays.','https://www.fpasrilanka.org/ask-sri','37/27 Bullers Lane, Colombo 07, Sri Lanka','anonymous sexual-health information and clinic referral',array['service','relax']::text[],'Safe Circles and FPA Sri Lanka')
), upd as (update public.services x set type=s.type,provider_name=s.provider_name,contact=s.contact,booking_link=s.booking_link,description=s.description,hours=s.hours,link=s.link,location=s.location,vibe=s.vibe,vibe_tags=s.tags,source=s.source,"lastChecked"='2026-09-14'::date,verified=true from s where lower(trim(x.city))='colombo' and lower(trim(x.name))=lower(trim(s.name)) returning x.id)
insert into public.services(name,city,type,provider_name,contact,booking_link,description,hours,link,image_urls,location,lat,lng,price_tier,vibe,vibe_tags,source,"lastChecked",verified) select name,'colombo',type,provider_name,contact,booking_link,description,hours,link,array[]::text[],location,6.9271,79.8612,'$',vibe,tags,source,'2026-09-14'::date,true from s where not exists(select 1 from public.services x where lower(trim(x.city))='colombo' and lower(trim(x.name))=lower(trim(s.name)));

insert into public.qa_country_rights_profiles(country,legal_level,rights_level,safety_level,same_sex_relations_status,union_status,legal_gender_recognition_status,anti_discrimination_status,what_this_means,confidence,source_legal_url,source_rights_url,source_safety_url,source_checked_at,needs_manual_review) values ('Sri Lanka','risk','risk','risk','criminalized','no_protection','restricted','limited_or_none','Consensual same-sex intimacy remains criminalised under Penal Code sections 365 and 365A. Repeal has judicial support but has not become law; relationship recognition and broad sector protections are absent, while police abuse and discrimination remain documented.','high','https://www.equaldex.com/region/sri-lanka','https://www.hrw.org/world-report/2024/country-chapters/sri-lanka','https://www.hrw.org/report/2016/08/16/all-five-fingers-are-not-same/discrimination-grounds-gender-identity-and-sexual','2026-09-14'::date,false) on conflict(country) do update set legal_level=excluded.legal_level,rights_level=excluded.rights_level,safety_level=excluded.safety_level,same_sex_relations_status=excluded.same_sex_relations_status,union_status=excluded.union_status,legal_gender_recognition_status=excluded.legal_gender_recognition_status,anti_discrimination_status=excluded.anti_discrimination_status,what_this_means=excluded.what_this_means,confidence=excluded.confidence,source_legal_url=excluded.source_legal_url,source_rights_url=excluded.source_rights_url,source_safety_url=excluded.source_safety_url,source_checked_at=excluded.source_checked_at,needs_manual_review=excluded.needs_manual_review;

insert into public.qa_qari_profiles(destination_key,scope_type,country,city_key,legal_risk,social_risk,digital_risk,risk_floor,confidence,summary,methodology_version,reviewed_by,reviewed_at,is_published) values ('country:sri-lanka','country','Sri Lanka',null,88,72,45,70,'high','Same-sex intimacy remains criminalised, with no relationship recognition and only narrow protection from discrimination. Colombo has active advocacy and Pride infrastructure, but low acceptance and documented police abuse make discretion essential.','1.0','Queer Atlas editorial review','2026-09-14'::date,true) on conflict(destination_key) do update set legal_risk=excluded.legal_risk,social_risk=excluded.social_risk,digital_risk=excluded.digital_risk,risk_floor=excluded.risk_floor,confidence=excluded.confidence,summary=excluded.summary,methodology_version=excluded.methodology_version,reviewed_by=excluded.reviewed_by,reviewed_at=excluded.reviewed_at,is_published=excluded.is_published;
delete from public.qa_qari_sources where destination_key='country:sri-lanka';
insert into public.qa_qari_sources(destination_key,axis,source_type,label,url,supports_claim,published_at,checked_at) values
('country:sri-lanka','legal','legal_database','Equaldex · Sri Lanka','https://www.equaldex.com/region/sri-lanka','Documents criminalisation, absent union recognition and limited protections.',null,'2026-09-14'::date),
('country:sri-lanka','social','legal_database','Equaldex · Sri Lanka public opinion','https://www.equaldex.com/region/sri-lanka','Reports 25% describing their area as a good place for gay and lesbian people in 2024.',null,'2026-09-14'::date),
('country:sri-lanka','digital','ngo_report','Human Rights Watch · Sri Lanka','https://www.hrw.org/world-report/2024/country-chapters/sri-lanka','Documents criminalising law, trans-targeting provisions and reform status.','2024-01-11'::date,'2026-09-14'::date),
('country:sri-lanka','social','ngo_report','EQUAL GROUND · Community and counselling','https://www.equal-ground.org/our-work/','Documents active counselling, safe-space and national advocacy infrastructure.',null,'2026-09-14'::date);
commit;
